24: var TOKEN_CLEANUP_MINUTES = 15;
25: var TOKEN_CLEANUP_TIMER = TOKEN_CLEANUP_MINUTES * 60 * 1000;
26: 
27: function cleanupToken(tokenId) {
28:   check(tokenId, String);
29:   waitPromise(sandstormBackend.deleteBackup(tokenId));
30:   FileTokens.remove({_id: tokenId});
31: }
