33: Meteor.startup(function () {
34:   // Cleanup tokens every TOKEN_CLEANUP_MINUTES
35:   Meteor.setInterval(function () {
36:     var queryDate = new Date(Date.now() - TOKEN_CLEANUP_TIMER);
37: 
38:     FileTokens.find({timestamp: {$lt: queryDate}}).forEach(function (token) {
39:       cleanupToken(token._id);
40:     });
41:   }, TOKEN_CLEANUP_TIMER);
42: });
