44: Meteor.methods({
45:   backupGrain: function (grainId) {
46:     check(grainId, String);
47:     var grain = Grains.findOne(grainId);
48:     if (!grain || !this.userId || grain.userId !== this.userId) {
49:       throw new Meteor.Error(403, "Unauthorized", "User is not the owner of this grain");
50:     }
51: 
52:     this.unblock();
53: 
54:     var token = {
55:       _id: Random.id(),
56:       timestamp: new Date(),
57:       name: grain.title
58:     };
59: 
60:     // TODO(soon): does the grain need to be offline?
61: 
62:     var grainInfo = _.pick(grain, "appId", "appVersion", "title");
63: 
64:     FileTokens.insert(token);
65:     waitPromise(sandstormBackend.backupGrain(token._id, this.userId, grainId, grainInfo));
66: 
67:     return token._id;
68:   },
