70:   restoreGrain: function (tokenId) {
71:     check(tokenId, String);
72:     var token = FileTokens.findOne(tokenId);
73:     if (!token || !isSignedUpOrDemo()) {
74:       throw new Meteor.Error(403, "Unauthorized",
75:           "Token was not found, or user cannot create grains");
76:     }
77: 
78:     this.unblock();
79: 
80:     var grainId = Random.id(22);
81: 
82:     try {
83:       var grainInfo = waitPromise(sandstormBackend.restoreGrain(tokenId, this.userId, grainId)).info;
84:       if (!grainInfo.appId) {
85:           throw new Meteor.Error(500, "Metadata object for uploaded grain has no AppId");
86:       }
87: 
88:       var action = UserActions.findOne({appId: grainInfo.appId, userId: this.userId});
89:       if (!action) {
90:         throw new Meteor.Error(500,
91:                                "App id for uploaded grain not installed",
92:                                "App Id: " + grainInfo.appId);
93:       }
94:       if (action.appVersion < grainInfo.appVersion) {
95:         throw new Meteor.Error(500,
96:                                "App version for uploaded grain is newer than any " +
97:                                "installed version. You need to upgrade your app first",
98:                                "New version: " + grainInfo.appVersion +
99:                                ", Old version: " + action.appVersion);
100:       }
101: 
102:       Grains.insert({
103:         _id: grainId,
104:         packageId: action.packageId,
105:         appId: action.appId,
106:         appVersion: action.appVersion,
107:         userId: this.userId,
108:         title: grainInfo.title,
109:         private: true
110:       });
111:     } finally {
112:       cleanupToken(tokenId);
113:     }
114: 
115:     return grainId;
116:   },
117: });
