201:               stream.write(data);
202:             });
203:             request.on("end", function () {
204:               resolve(stream.done());
205:             });
206:             request.on("error", function (err) {
207:               stream.close();
208:             });
209:           }));
210: 
211:           this.response.writeHead(200, {
212:             "Content-Length": token._id.length,
213:             "Content-Type": "text/plain"
214:           });
215:           this.response.write(token._id);
216:           this.response.end();
217:         } catch(error) {
218:           console.error(error.stack);
219:           this.response.writeHead(500, {
220:             "Content-Type": "text/plain"
221:           });
222:           this.response.write(error.stack);
223:           this.response.end();
224:         }
225:       } else {
226:         this.response.writeHead(405, {
227:           "Content-Type": "text/plain"
228:         });
